/**
 * ブラウザからエージェントを呼ぶ許可と、サーバーのコードからエージェントを呼ぶ関数。
 * Flue の app.ts と、同じプロセスで動くフロントエンドのサーバーのコードの両方から使う。
 * 登録先はプロセスの中の globalThis の Symbol の鍵に置く。
 * Flue のアプリと SDK のサーバーの入口が、それぞれ別の写しの @rouar/sdk を読み込んでも、同じ登録先を見るため
 */
import type { IncomingMessage, ServerResponse } from "node:http";

/** 許可の関数が返す値。principal は呼び出し元を表す、利用者が決めた文字列 */
export type BrowserPrincipal = { principal: string };

/** 許可の関数に渡す、要求の本文のほかの情報 */
export type BrowserAuthorizeContext = {
	/**
	 * Node の要求と応答。フレームワークのセッションの仕組みで確かめる包みのために渡す。
	 * 本文は読まないこと。読むとエージェントに本文が届かない
	 */
	node?: { req: IncomingMessage; res: ServerResponse };
};

/**
 * 要求ごとに呼ぶ許可の関数。許すなら呼び出し元を返し、断るなら null か undefined を返す。
 * 渡す要求は本文を持たない写しで、URL と見出しは元の要求と同じ
 */
export type BrowserAuthorize = (
	request: Request,
	context: BrowserAuthorizeContext,
) =>
	| BrowserPrincipal
	| null
	| undefined
	| Promise<BrowserPrincipal | null | undefined>;

export type AllowBrowserAgentsOptions = {
	authorize: BrowserAuthorize;
};

/** SDK のサーバーの入口が登録する、プロセスの中の Flue の fetch を呼ぶ関数 */
export type InProcessAgentFetch = (
	request: Request,
	principal: string | undefined,
) => Promise<Response>;

type Registry = {
	authorize?: BrowserAuthorize;
	agentFetch?: InProcessAgentFetch;
};

const REGISTRY_KEY = Symbol.for("rouar.sdk.browser-agents");

/** 呼び出し元をエージェントに渡す見出し。利用者が送った値は捨てる */
export const PRINCIPAL_HEADER = "x-rouar-principal";

/** 呼び出し元の文字列の上限。見出しに入れるので、表示できる ASCII に限る */
const PRINCIPAL_MAX_LENGTH = 256;
const PRINCIPAL_PATTERN = /^[\x20-\x7e]+$/;

/** @internal 呼び出し元の文字列が使えるかを確かめる */
export function isValidPrincipal(value: unknown): value is string {
	return (
		typeof value === "string" &&
		value.trim().length > 0 &&
		value.length <= PRINCIPAL_MAX_LENGTH &&
		PRINCIPAL_PATTERN.test(value)
	);
}

function registry(): Registry {
	const holder = globalThis as { [REGISTRY_KEY]?: Registry };
	holder[REGISTRY_KEY] ??= {};
	return holder[REGISTRY_KEY];
}

/**
 * ブラウザから、同じオリジンのエージェントの会話の URL を、アクセストークンなしで呼べるようにする。
 * authorize は要求ごとに呼ばれ、許すなら呼び出し元を返す。会話は呼び出し元ごとに分かれる。
 * もう一度呼ぶと、前の関数を置き換える
 */
export function allowBrowserAgents(options: AllowBrowserAgentsOptions): void {
	if (typeof options?.authorize !== "function") {
		throw new TypeError(
			"[rouar] allowBrowserAgents() needs an authorize function.",
		);
	}
	registry().authorize = options.authorize;
}

/** @internal 登録された許可の関数を返す。SDK のサーバーの入口が使う */
export function getBrowserAuthorize(): BrowserAuthorize | undefined {
	return registry().authorize;
}

/** @internal 許可の関数の登録を外す。テストで使う */
export function resetBrowserAgentsForTests(): void {
	const current = registry();
	delete current.authorize;
	delete current.agentFetch;
}

/** @internal SDK のサーバーの入口が、Flue のアプリを読み込んだあとに登録する */
export function registerInProcessAgentFetch(
	fetch: InProcessAgentFetch | undefined,
): void {
	registry().agentFetch = fetch;
}

export type AgentFetchOptions = {
	/**
	 * 呼び出し元。渡すと、ブラウザから呼んだときと同じく会話を呼び出し元ごとに分け、
	 * x-rouar-principal でエージェントに渡す。省くと、アクセストークンで呼んだときと同じく分けない
	 */
	principal?: string;
};

/**
 * 同じプロセスの Flue のアプリを、アクセストークンなしで直接呼ぶ。
 * フロントエンドのサーバーのコードから使う。Rouar のサーバーの入口の外では使えない。
 * パスだけを渡すと、内部のホストの URL として扱う
 */
export async function agentFetch(
	input: Request | URL | string,
	options: AgentFetchOptions = {},
): Promise<Response> {
	const fetch = registry().agentFetch;
	if (!fetch) {
		throw new Error(
			"[rouar] agentFetch() works only inside the rouar server. Run the app with the rouar server entry, or call the agent over HTTP with an access token.",
		);
	}
	const request =
		input instanceof Request
			? input
			: new Request(new URL(input, "http://rouar.internal"));
	return fetch(request, options.principal);
}
